"""Deciders must use the same preparation protocol as other declarations."""

import unittest

import factory


class MaybeDeciderContextTests(unittest.TestCase):
    def test_faker_decider_defaults_are_unrolled(self):
        for chance, expected in [(0, 'no'), (100, 'yes')]:
            with self.subTest(chance=chance):
                class ExampleFactory(factory.DictFactory):
                    result = factory.Maybe(
                        factory.Faker(
                            'pybool',
                            locale='en_US',
                            truth_probability=factory.LazyFunction(lambda: chance),
                        ),
                        yes_declaration='yes',
                        no_declaration='no',
                    )

                self.assertEqual(ExampleFactory()['result'], expected)

    def test_nested_maybe_decider(self):
        class ExampleFactory(factory.DictFactory):
            result = factory.Maybe(
                factory.Maybe(factory.LazyFunction(lambda: True), True, False),
                yes_declaration='yes',
                no_declaration='no',
            )

        self.assertEqual(ExampleFactory()['result'], 'yes')

    def test_overrides_go_to_selected_branch_not_decider(self):
        class ExampleFactory(factory.DictFactory):
            result = factory.Maybe(
                factory.Faker('pybool', truth_probability=100),
                yes_declaration=factory.Dict({'value': 'default'}),
                no_declaration=None,
            )

        self.assertEqual(
            ExampleFactory(result__value='override')['result'],
            {'value': 'override'},
        )
PY
